import React from "react";
import { LucideIcon } from "lucide-react";

interface EmptyStateProps {
  icon: LucideIcon;
  title: string;
  description: string;
  actionLabel?: string;
  onAction?: () => void;
  isLoading?: boolean;
}

export const EmptyState: React.FC<EmptyStateProps> = ({
  icon: Icon,
  title,
  description,
  actionLabel,
  onAction,
  isLoading = false,
}) => {
  return (
    <div className="flex flex-col items-center justify-center p-8 text-center rounded-xl border border-dashed border-[#2A3554] bg-[#0E1529]/50 my-4">
      <div className="p-3 rounded-full bg-[#18233D] text-[#4CC9F0] mb-3">
        <Icon className={`w-6 h-6 ${isLoading ? "animate-spin" : ""}`} />
      </div>
      <h4 className="text-sm font-semibold text-[#E8EEFC] mb-1">{title}</h4>
      <p className="text-xs text-[#9AA8C7] max-w-sm mb-4 leading-relaxed">{description}</p>
      {actionLabel && onAction && (
        <button
          onClick={onAction}
          disabled={isLoading}
          className="px-4 py-2 text-xs font-semibold rounded-lg bg-[#4CC9F0] text-[#0B1020] hover:bg-[#4CC9F0]/90 transition-colors disabled:opacity-50 cursor-pointer"
        >
          {isLoading ? "Processing..." : actionLabel}
        </button>
      )}
    </div>
  );
};
