import React, { useEffect, useState } from "react";
import {
  Activity,
  AlertOctagon,
  AlertTriangle,
  CheckCircle,
  CheckCircle2,
  DollarSign,
  FileCode,
  Gauge,
  HelpCircle,
  Lock,
  Play,
  RefreshCw,
  Scale,
  Shield,
  ShieldAlert,
  ShieldCheck,
  XCircle,
} from "lucide-react";
import { api } from "../api/client";
import { JsonViewer } from "../components/JsonViewer";
import { KpiCard } from "../components/KpiCard";
import { Modal } from "../components/Modal";
import { StatusBadge } from "../components/StatusBadge";
import { AccountInfo, PublicSettings, RiskCheckResponse } from "../types/api";

export const RiskPage: React.FC = () => {
  const [account, setAccount] = useState<AccountInfo | null>(null);
  const [settings, setSettings] = useState<PublicSettings | null>(null);
  const [loading, setLoading] = useState(true);

  // Simulator state
  const [simSymbol, setSimSymbol] = useState("SPY");
  const [simDirection, setSimDirection] = useState<"bullish" | "bearish">("bullish");
  const [simMaxDebit, setSimMaxDebit] = useState(1500);
  const [simResult, setSimResult] = useState<RiskCheckResponse | null>(null);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simError, setSimError] = useState<string | null>(null);

  // Modal
  const [inspectModal, setInspectModal] = useState<{ title: string; data: any } | null>(null);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        const [acc, set] = await Promise.all([api.getAccount(), api.getSettings()]);
        setAccount(acc);
        setSettings(set);
      } catch (err) {
        // error handling
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const handleRunSimulator = async () => {
    try {
      setIsSimulating(true);
      setSimError(null);
      setSimResult(null);

      // Step 1: create proposal
      const prop = await api.createProposal(simSymbol, simDirection, simMaxDebit);
      if (!prop.accepted) {
        throw new Error(prop.rejection_reason || "Options selector could not find valid strikes.");
      }

      // Step 2: run risk gate
      const risk = await api.checkRisk({
        proposal: prop,
        proposal_id: prop.proposal_id,
      });
      setSimResult(risk);
    } catch (err: any) {
      setSimError(err.message || "Risk simulation failed");
    } finally {
      setIsSimulating(false);
    }
  };

  const equity = account?.equity || 100000;
  const maxRiskPerTradeDollars = equity * 0.015; // 1.5%
  const maxTotalPremiumDollars = equity * 0.20; // 20%
  const maxDailyLossDollars = equity * 0.03; // 3%
  const maxDrawdownDollars = equity * 0.08; // 8%

  const deterministicRules = [
    {
      id: "paper_trading_required",
      title: "Hard Paper Lock",
      desc: "Mandatory ALPACA_PAPER=true. Refuses to execute in live mode, guaranteeing safety.",
      severity: "critical",
    },
    {
      id: "max_risk_per_trade_exceeded",
      title: "Max Risk Per Trade (1.5%)",
      desc: `Loss capped at 1.5% of equity ($${maxRiskPerTradeDollars.toFixed(0)} max risk per trade).`,
      severity: "high",
    },
    {
      id: "max_daily_loss_exceeded",
      title: "Max Daily Loss Limit (3.0%)",
      desc: `Circuit breaker stops new trades if intraday drawdown exceeds 3% ($${maxDailyLossDollars.toFixed(0)}).`,
      severity: "high",
    },
    {
      id: "max_drawdown_exceeded",
      title: "Max Total Drawdown (8.0%)",
      desc: `Halt trigger if cumulative equity drops 8% ($${maxDrawdownDollars.toFixed(0)}) from peak.`,
      severity: "critical",
    },
    {
      id: "unsupported_or_naked_option_structure",
      title: "Zero Naked Options Policy",
      desc: "Only defined-risk debit spreads or fully covered option structures permitted.",
      severity: "critical",
    },
    {
      id: "max_open_option_trades_exceeded",
      title: "Max Open Positions (5)",
      desc: "Total active options positions cannot exceed 5 simultaneous spreads.",
      severity: "medium",
    },
    {
      id: "max_same_underlying_exposure_exceeded",
      title: "Single Underlying Cap (2)",
      desc: "Maximum 2 concurrent positions in the same stock to prevent concentration risk.",
      severity: "medium",
    },
    {
      id: "max_total_premium_deployed_exceeded",
      title: "Total Premium Ceiling (20%)",
      desc: `Aggregate deployed premium capped at 20% of account ($${maxTotalPremiumDollars.toFixed(0)}).`,
      severity: "high",
    },
    {
      id: "option_spread_too_wide",
      title: "Bid/Ask Liquidity Filter (< 20%)",
      desc: "Blocks contracts where (Ask - Bid) / Mid exceeds 20% to prevent excessive slippage.",
      severity: "medium",
    },
    {
      id: "stale_option_quote",
      title: "Quote Freshness (< 15 min)",
      desc: "Disallows stale market data older than 15 minutes.",
      severity: "medium",
    },
    {
      id: "expiration_too_close",
      title: "Expiration Horizon (> 7 DTE)",
      desc: "Avoids gamma risk and 0DTE decay by requiring contracts to expire 7 to 30 days out.",
      severity: "medium",
    },
    {
      id: "inside_end_of_day_entry_cutoff",
      title: "End-of-Day Entry Cutoff",
      desc: "No new trade entries permitted in the final 10 minutes of the market session.",
      severity: "low",
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="glass-panel rounded-2xl p-5 border border-[#2A3554] bg-gradient-to-r from-[#121A2F] to-[#0B1020]">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div>
            <div className="flex items-center gap-2">
              <span className="p-1.5 rounded-lg bg-[#F4B942]/10 text-[#F4B942]">
                <ShieldAlert className="w-5 h-5" />
              </span>
              <h2 className="text-lg font-bold text-[#E8EEFC]">
                Deterministic Risk Governance Console
              </h2>
              <StatusBadge variant="ok">All 18 Gates Armed</StatusBadge>
            </div>
            <p className="mt-1 text-xs text-[#9AA8C7] max-w-2xl">
              FlightDeck Alpha decouples LLM generation from execution approval. Every proposed trade
              must pass deterministic, mathematically pure risk gates before order submission.
            </p>
          </div>

          <div className="flex items-center gap-2">
            <StatusBadge variant="ok" pulse>
              Live Enforcement
            </StatusBadge>
          </div>
        </div>
      </div>

      {/* Portfolio Risk Limits & Capacity */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard
          label="Max Risk / Trade"
          value={`$${maxRiskPerTradeDollars.toFixed(0)}`}
          subtitle="1.5% max defined risk of equity"
          icon={Shield}
          variant="warn"
        />
        <KpiCard
          label="Max Premium Deployed"
          value={`$${maxTotalPremiumDollars.toFixed(0)}`}
          subtitle="20.0% of portfolio equity"
          icon={DollarSign}
          variant="cyan"
        />
        <KpiCard
          label="Max Daily Loss Cap"
          value={`$${maxDailyLossDollars.toFixed(0)}`}
          subtitle="3.0% circuit breaker stop"
          icon={AlertOctagon}
          variant="negative"
        />
        <KpiCard
          label="Max Total Drawdown"
          value={`$${maxDrawdownDollars.toFixed(0)}`}
          subtitle="8.0% cumulative equity protection"
          icon={Scale}
          variant="negative"
        />
      </div>

      {/* Interactive Risk Gate Simulator */}
      <div className="glass-panel rounded-2xl p-5 border border-[#2A3554]">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-4">
          <div>
            <h3 className="text-sm font-bold text-[#E8EEFC] flex items-center gap-2">
              <Play className="w-4 h-4 text-[#4CC9F0]" />
              <span>Interactive Risk Gate Simulator</span>
            </h3>
            <span className="text-[11px] text-[#6E7A99]">
              Test any hypothetical options debit spread through the 18 risk gates
            </span>
          </div>

          <button
            onClick={handleRunSimulator}
            disabled={isSimulating}
            className="px-4 py-2 rounded-xl bg-[#4CC9F0] text-[#0B1020] font-bold text-xs hover:bg-[#4CC9F0]/90 transition-colors disabled:opacity-50 cursor-pointer flex items-center gap-1.5 shadow-md shadow-[#4CC9F0]/10"
          >
            <ShieldCheck className={`w-3.5 h-3.5 ${isSimulating ? "animate-spin" : ""}`} />
            <span>{isSimulating ? "Evaluating Risk..." : "Evaluate Risk Gate"}</span>
          </button>
        </div>

        {/* Parameter Inputs */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-4 rounded-xl bg-[#0E1529] border border-[#2A3554]">
          <div>
            <label className="text-[11px] font-semibold uppercase tracking-wider text-[#6E7A99] block mb-1">
              Underlying Symbol
            </label>
            <select
              value={simSymbol}
              onChange={(e) => setSimSymbol(e.target.value)}
              className="w-full bg-[#121A2F] border border-[#2A3554] rounded-lg px-3 py-2 text-xs font-mono font-bold text-[#E8EEFC] focus:border-[#4CC9F0]"
            >
              {["SPY", "QQQ", "IWM", "AAPL", "NVDA", "MSFT", "TSLA", "META", "AMZN", "GOOGL", "AMD"].map(
                (s) => (
                  <option key={s} value={s}>
                    {s}
                  </option>
                )
              )}
            </select>
          </div>

          <div>
            <label className="text-[11px] font-semibold uppercase tracking-wider text-[#6E7A99] block mb-1">
              Strategy Direction
            </label>
            <select
              value={simDirection}
              onChange={(e) => setSimDirection(e.target.value as any)}
              className="w-full bg-[#121A2F] border border-[#2A3554] rounded-lg px-3 py-2 text-xs font-mono text-[#E8EEFC] focus:border-[#4CC9F0]"
            >
              <option value="bullish">Bull Call Debit Spread</option>
              <option value="bearish">Bear Put Debit Spread</option>
            </select>
          </div>

          <div>
            <label className="text-[11px] font-semibold uppercase tracking-wider text-[#6E7A99] block mb-1">
              Max Debit Budget ($)
            </label>
            <input
              type="number"
              value={simMaxDebit}
              onChange={(e) => setSimMaxDebit(Number(e.target.value))}
              min={100}
              max={10000}
              step={100}
              className="w-full bg-[#121A2F] border border-[#2A3554] rounded-lg px-3 py-2 text-xs font-mono font-bold text-[#E8EEFC] focus:border-[#4CC9F0]"
            />
          </div>
        </div>

        {simError && (
          <div className="mt-3 p-3 rounded-xl border border-rose-500/30 bg-rose-500/10 text-xs text-[#FF6B6B]">
            {simError}
          </div>
        )}

        {/* Simulation Output */}
        {simResult && (
          <div className="mt-4 pt-4 border-t border-[#2A3554] space-y-3 animate-in fade-in">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <StatusBadge
                  variant={simResult.approved ? "ok" : "danger"}
                  pulse={simResult.approved}
                  size="md"
                >
                  {simResult.approved ? "TRADE RISK APPROVED" : "TRADE RISK BLOCKED"}
                </StatusBadge>
                <span className="font-mono text-xs text-[#9AA8C7]">
                  Evaluated at {new Date(simResult.timestamp).toLocaleTimeString()}
                </span>
              </div>

              <button
                onClick={() => setInspectModal({ title: "Risk Check Result", data: simResult })}
                className="text-xs text-[#4CC9F0] underline font-mono cursor-pointer"
              >
                Inspect Result JSON
              </button>
            </div>

            {simResult.approved ? (
              <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs text-[#3DD68C]">
                <strong>Passed:</strong> Sizing within limits. Max loss: $
                {simResult.computed_risk?.max_loss} ({simResult.computed_risk?.risk_pct_of_equity}% of
                equity).
              </div>
            ) : (
              <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs space-y-1">
                <strong className="text-[#FF6B6B]">Blocking Reasons:</strong>
                <ul className="list-disc list-inside text-xs font-mono text-[#F4B942]">
                  {simResult.blocking_reasons.map((r, i) => (
                    <li key={i}>{r}</li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}
      </div>

      {/* 18 Deterministic Risk Gates Matrix */}
      <div className="glass-panel rounded-2xl p-5">
        <div className="mb-4">
          <h3 className="text-sm font-bold text-[#E8EEFC] flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-[#3DD68C]" />
            <span>Deterministic Risk Gate Policies (Source: backend/app/trading/risk.py)</span>
          </h3>
          <span className="text-[11px] text-[#6E7A99]">
            Pure deterministic code enforcing non-negotiable capital safety rules
          </span>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
          {deterministicRules.map((rule) => (
            <div
              key={rule.id}
              className="p-3.5 rounded-xl border border-[#2A3554] bg-[#0E1529]/60 hover:bg-[#121A2F] transition-colors space-y-1.5"
            >
              <div className="flex items-center justify-between">
                <span className="font-semibold text-xs text-[#E8EEFC] flex items-center gap-1.5">
                  <CheckCircle2 className="w-3.5 h-3.5 text-[#3DD68C]" />
                  <span>{rule.title}</span>
                </span>
                <StatusBadge
                  variant={rule.severity === "critical" ? "danger" : rule.severity === "high" ? "warn" : "info"}
                  size="sm"
                >
                  {rule.severity.toUpperCase()}
                </StatusBadge>
              </div>
              <p className="text-xs text-[#9AA8C7] leading-relaxed">{rule.desc}</p>
              <div className="text-[10px] font-mono text-[#6E7A99] pt-1">
                Policy Code: <span className="text-[#4CC9F0]">{rule.id}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Modal */}
      {inspectModal && (
        <Modal isOpen={true} onClose={() => setInspectModal(null)} title={inspectModal.title}>
          <JsonViewer data={inspectModal.data} title={inspectModal.title} />
        </Modal>
      )}
    </div>
  );
};
