import React from "react";

export type BadgeVariant = "ok" | "warn" | "danger" | "info" | "neutral" | "cyan" | "violet";

interface StatusBadgeProps {
  variant?: BadgeVariant;
  children: React.ReactNode;
  pulse?: boolean;
  className?: string;
  size?: "sm" | "md";
}

export const StatusBadge: React.FC<StatusBadgeProps> = ({
  variant = "neutral",
  children,
  pulse = false,
  className = "",
  size = "md",
}) => {
  const variantStyles: Record<BadgeVariant, { bg: string; text: string; border: string; dot: string }> = {
    ok: {
      bg: "bg-emerald-500/10",
      text: "text-[#3DD68C]",
      border: "border-emerald-500/25",
      dot: "bg-[#3DD68C]",
    },
    warn: {
      bg: "bg-amber-500/10",
      text: "text-[#F4B942]",
      border: "border-amber-500/25",
      dot: "bg-[#F4B942]",
    },
    danger: {
      bg: "bg-rose-500/10",
      text: "text-[#FF6B6B]",
      border: "border-rose-500/25",
      dot: "bg-[#FF6B6B]",
    },
    info: {
      bg: "bg-cyan-500/10",
      text: "text-[#4CC9F0]",
      border: "border-cyan-500/25",
      dot: "bg-[#4CC9F0]",
    },
    cyan: {
      bg: "bg-cyan-500/10",
      text: "text-[#4CC9F0]",
      border: "border-cyan-500/25",
      dot: "bg-[#4CC9F0]",
    },
    violet: {
      bg: "bg-violet-500/10",
      text: "text-[#7B61FF]",
      border: "border-violet-500/25",
      dot: "bg-[#7B61FF]",
    },
    neutral: {
      bg: "bg-slate-800/60",
      text: "text-[#9AA8C7]",
      border: "border-[#2A3554]",
      dot: "bg-[#9AA8C7]",
    },
  };

  const style = variantStyles[variant];
  const sizeClasses = size === "sm" ? "px-2 py-0.5 text-xs" : "px-2.5 py-1 text-xs font-medium";

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full border ${style.bg} ${style.text} ${style.border} ${sizeClasses} ${className}`}
    >
      {pulse && (
        <span className="relative flex h-2 w-2">
          <span
            className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${style.dot}`}
          />
          <span className={`relative inline-flex rounded-full h-2 w-2 ${style.dot}`} />
        </span>
      )}
      <span>{children}</span>
    </span>
  );
};
