import React, { useState } from "react";
import { Check, Copy } from "lucide-react";

interface JsonViewerProps {
  data: any;
  title?: string;
  maxHeight?: string;
}

export const JsonViewer: React.FC<JsonViewerProps> = ({
  data,
  title,
  maxHeight = "max-h-96",
}) => {
  const [copied, setCopied] = useState(false);
  const formatted = typeof data === "string" ? data : JSON.stringify(data, null, 2);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(formatted);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback
    }
  };

  return (
    <div className="rounded-lg border border-[#2A3554] bg-[#070B14] overflow-hidden text-xs">
      <div className="flex items-center justify-between px-3 py-1.5 bg-[#121A2F] border-b border-[#2A3554]">
        <span className="font-mono text-[11px] text-[#9AA8C7] font-medium">
          {title || "JSON Payload"}
        </span>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1 px-2 py-0.5 rounded text-[11px] text-[#9AA8C7] hover:text-[#E8EEFC] hover:bg-[#18233D] transition-colors cursor-pointer"
          title="Copy to clipboard"
        >
          {copied ? (
            <>
              <Check className="w-3 h-3 text-[#3DD68C]" />
              <span className="text-[#3DD68C]">Copied</span>
            </>
          ) : (
            <>
              <Copy className="w-3 h-3" />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>
      <pre
        className={`p-3 font-mono text-[12px] leading-relaxed text-[#4CC9F0] overflow-x-auto overflow-y-auto ${maxHeight} selection:bg-[#4CC9F0]/20`}
      >
        <code>{formatted}</code>
      </pre>
    </div>
  );
};
