import React from "react";
import { LucideIcon } from "lucide-react";

interface KpiCardProps {
  label: string;
  value: string | number;
  subtitle?: string;
  delta?: {
    value: string | number;
    isPositive: boolean;
  };
  icon?: LucideIcon;
  variant?: "default" | "positive" | "negative" | "cyan" | "warn";
  onClick?: () => void;
  className?: string;
}

export const KpiCard: React.FC<KpiCardProps> = ({
  label,
  value,
  subtitle,
  delta,
  icon: Icon,
  variant = "default",
  onClick,
  className = "",
}) => {
  const valueColor = {
    default: "text-[#E8EEFC]",
    positive: "text-[#3DD68C]",
    negative: "text-[#FF6B6B]",
    cyan: "text-[#4CC9F0]",
    warn: "text-[#F4B942]",
  }[variant];

  return (
    <div
      onClick={onClick}
      className={`glass-panel rounded-xl p-4 flex flex-col justify-between transition-colors duration-200 ${
        onClick ? "cursor-pointer glass-panel-hover" : ""
      } ${className}`}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#9AA8C7]">
          {label}
        </span>
        {Icon && (
          <div className="p-1.5 rounded-md bg-[#18233D] text-[#4CC9F0]">
            <Icon className="w-4 h-4" />
          </div>
        )}
      </div>

      <div className="mt-2 flex items-baseline gap-2">
        <span className={`font-mono text-2xl font-bold tracking-tight tabular-nums ${valueColor}`}>
          {value}
        </span>
        {delta && (
          <span
            className={`font-mono text-xs font-semibold tabular-nums ${
              delta.isPositive ? "text-[#3DD68C]" : "text-[#FF6B6B]"
            }`}
          >
            {delta.isPositive ? "+" : ""}
            {delta.value}
          </span>
        )}
      </div>

      {subtitle && (
        <span className="mt-1 text-xs text-[#6E7A99] truncate">
          {subtitle}
        </span>
      )}
    </div>
  );
};
